<?php
namespace App\Console\Commands;use Illuminate\Console\Command;use Illuminate\Support\Facades\DB;use App\Models\{User,CrmAccountAllocation};use App\Services\{ClientRelationsPipeline,PerformanceWorkflow};
class ImportCrmAllocations extends Command {protected $signature='crm:import-allocations {file} {--owner-map=} {--actor=}';protected $description='Copy labelled account allocations without inventing reporting periods';public function handle():int{$data=json_decode(file_get_contents($this->argument('file')),true,512,JSON_THROW_ON_ERROR);$map=json_decode(file_get_contents($this->option('owner-map')),true,512,JSON_THROW_ON_ERROR);$actor=User::findOrFail($this->option('actor'));abort_unless(ClientRelationsPipeline::member($actor)&&$actor->isLineManager(),403);if(($data['source_id']??null)!=='1ydsMLK86iDG5XPp1PcC3_qjh_2CjeJ_-')throw new \RuntimeException('Unexpected workbook');$count=0;DB::transaction(function()use($data,$map,$actor,&$count){foreach($data['rows'] as $row){$owner=!empty($row['owner_sheet'])?User::findOrFail($map[$row['owner_sheet']]??0):null;if($owner)abort_unless(ClientRelationsPipeline::historicalOwner($owner),422);$key=hash('sha256',$data['source_id'].'|allocation|'.$row['sheet'].'|'.$row['row']);if(CrmAccountAllocation::where('import_key',$key)->exists())continue;$item=CrmAccountAllocation::create(['import_key'=>$key,'client_name'=>$row['client'],'owner_id'=>$owner?->id,'reported_owner'=>$row['reported_owner']??$owner?->name,'ytd_target'=>$row['ytd_target'],'monthly_target'=>$row['monthly_target'],'budget_target'=>$row['budget_target'],'reported_target'=>$row['reported_target'],'source_sheet'=>$row['sheet'],'source_row'=>$row['row'],'source_values'=>$row['source_values']]);PerformanceWorkflow::record('crm_allocation',$item->id,$actor->id,'import',[],$item->getAttributes(),'Source account allocation copied with its original field labels. No reporting date or actual revenue inferred.');$count++;}});$this->info(json_encode(['imported'=>$count,'total'=>CrmAccountAllocation::count()]));return self::SUCCESS;}}
